import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.time.*;
import java.io.*;
import java.util.*;

/** External measurement interpreter; no JVM attachment and no analyzer execution. */
public class QueryStageJfr {
    static class Window {
        final String name; final double begin,end; final Counts counts=new Counts();
        double pauseSeconds; long pauseEvents;
        Window(String n,double b,double e){name=n;begin=b;end=e;}
    }
    static class Trace {
        final List<String> frames; final String scope,site,observerComponent,fineDomain,fineStage;
        Set<String> unique;
        Trace(List<String> f,String s,String a){frames=f;scope=s;site=a;observerComponent=observerComponent(f); fineDomain=fineDomain(f); fineStage=fineStage(f,fineDomain);}
    }
    static class Counts {
        long samples,allocationSamples,allocationBytes,gcEvents; double gcPauses;
        final Map<String,Long> scopes=new HashMap<>(),leaf=new HashMap<>(),inclusive=new HashMap<>();
        final Map<String,Long> allocationScopes=new HashMap<>(),allocationClasses=new HashMap<>(),allocationSites=new HashMap<>();
        final Map<String,Long> observerSamples=new HashMap<>(),observerAllocation=new HashMap<>();
        final Map<String,Long> fineSamples=new HashMap<>(),fineAllocation=new HashMap<>(),fineAllocationClasses=new HashMap<>(),fineLeaf=new HashMap<>(),fineSourceLines=new HashMap<>(),fineApplicationSamples=new HashMap<>();
        final Map<String,List<List<String>>> examples=new HashMap<>();
        void add(String kind,RecordedEvent event,Trace trace){
            if(kind.equals("jdk.GarbageCollection")){gcEvents++;gcPauses+=seconds(event.getDuration("sumOfPauses"));return;}
            if(kind.equals("jdk.ExecutionSample") && !trace.frames.isEmpty()){
                samples++; inc(fineSamples,trace.fineDomain+"/"+trace.fineStage,1);inc(fineLeaf,trace.fineDomain+"/"+trace.fineStage+"/"+trace.frames.get(0),1);
                String direction=has(trace.frames,".LocalRelationApplication.applyRecordView")?"reverse":has(trace.frames,".LocalRelationApplication.applyRecord")?"direct":null; if(direction!=null)inc(fineApplicationSamples,trace.fineDomain+"/"+direction,1);
                for(RecordedFrame f:event.getStackTrace().getFrames()){RecordedMethod m=f.getMethod();String name=m.getType().getName()+"."+m.getName();if(name.contains(".BlockSummaryLinks.publish"))inc(fineSourceLines,name+":"+f.getLineNumber(),1);}
                inc(scopes,trace.scope,1);inc(leaf,trace.frames.get(0),1);if(trace.observerComponent!=null)inc(observerSamples,trace.observerComponent,1);
                if(trace.unique==null)trace.unique=new HashSet<>(trace.frames);
                for(String frame:trace.unique)inc(inclusive,frame,1);
                List<List<String>> xs=examples.computeIfAbsent(trace.scope,k->new ArrayList<>());
                if(xs.size()<5&&!xs.contains(trace.frames))xs.add(List.copyOf(trace.frames));
            }else if(kind.equals("jdk.ObjectAllocationSample")){
                long weight=event.getLong("weight");inc(fineAllocation,trace.fineDomain+"/"+trace.fineStage,weight);RecordedClass allocated=event.getClass("objectClass");inc(fineAllocationClasses,trace.fineDomain+"/"+trace.fineStage+"/"+(allocated==null?"?":className(allocated)),weight);allocationSamples++;allocationBytes+=weight;if(trace.observerComponent!=null)inc(observerAllocation,trace.observerComponent,weight);
                inc(allocationScopes,trace.scope,weight);inc(allocationSites,trace.site,weight);
                RecordedClass cls=event.getClass("objectClass");inc(allocationClasses,cls==null?"?":className(cls),weight);
            }
        }
        Map<String,Object> output(){
            Map<String,Object> o=new LinkedHashMap<>();o.put("samples",samples);o.put("scopes",scopes);o.put("leaf",leaf);o.put("inclusive",inclusive);
            o.put("allocation_samples",allocationSamples);o.put("allocation_bytes",allocationBytes);o.put("allocation_scopes",allocationScopes);
            o.put("allocation_classes",allocationClasses);o.put("allocation_sites",allocationSites);o.put("gc_events",gcEvents);o.put("gc_pause_seconds",gcPauses);o.put("observer_samples",observerSamples);o.put("observer_allocation",observerAllocation);o.put("examples",examples);o.put("fine_samples",fineSamples);o.put("fine_allocation",fineAllocation);o.put("fine_allocation_classes",fineAllocationClasses);o.put("fine_leaf",fineLeaf);o.put("fine_source_lines",fineSourceLines);o.put("fine_application_samples",fineApplicationSamples);return o;
        }
    }


    static boolean has(List<String> frames,String... anchors){for(String frame:frames)for(String anchor:anchors)if(frame.contains(anchor))return true;return false;}
    static String fineDomain(List<String> f){
        if(has(f,".LoopConsumerObservation", ".MethodBlockRuntime.observe"))return "loop_observer";
        if(has(f,".OwnedJoinedStaticWriterBinding.complete",".OwnedJoinedStaticWriterBinding$complete"))return "joined_static_binding";
        if(has(f,".BlockSummaryLinks.publish"))return "local_publication";
        if(has(f,".BlockSummaryLinks.deliver",".BlockSummaryLinks.drain"))return "local_delivery";
        if(has(f,".KilledStaticWriteStore.freeze",".JoinedStaticSource.freezeWrites"))return "static_prune";
        return "other";
    }
    static String fineStage(List<String> f,String domain){
        if(domain.equals("loop_observer")){
            int observerEnd=-1;for(int i=0;i<f.size();i++)if(has(List.of(f.get(i)),".LoopConsumerObservation", ".MethodBlockRuntime.observe"))observerEnd=i;
            f=f.subList(0,observerEnd+1);
            if(has(f,".DemandStore$prepareLocalDataPlan",".DemandStore.intersect",".DemandStore.offerDataPair",".BlockBoundaryDemandView.intersect",".DemandStore.acceptsTarget",".BlockBoundaryDemandView.acceptsTarget",".LoopQueryScratch.plan",".EntryRestrictionTicket.")){
                int c5End=-1;for(int i=0;i<f.size();i++)if(has(List.of(f.get(i)),".DemandStore$prepareLocalDataPlan",".DemandStore.intersect",".DemandStore.offerDataPair",".BlockBoundaryDemandView.intersect",".DemandStore.acceptsTarget",".BlockBoundaryDemandView.acceptsTarget",".LoopQueryScratch.plan",".EntryRestrictionTicket."))c5End=i;
                f=f.subList(0,c5End+1);
                if(has(f,".LimitKt.limitFacts",".FieldLimitCut.",".ApOps.limit"))return "C5_field_limit";
                if(has(f,".ReferenceKt.marksMeet",".ReferenceKt.markSub",".MarkTable.coversAtom"))return "C5_mark_match";
                if(has(f,".DemandKt.restrictFacts",".ReferenceKt.commonPart",".EntryRestrictionTicket.restrict"))return "C5_output_restrict";
                if(has(f,".EntryRestrictionTicket.prepare",".LoopQueryScratch.plan")&&!has(f,".DemandStore.offerDataPair",".DemandStore$prepareLocalDataPlan$2.intersect"))return "C5_prepare_or_plan_lookup";
                if(has(f,".PathTrie.")&&!has(f,".DemandStore.offerDataPair"))return "C5_output_path_index";
                if(has(f,".ExactDemandResults."))return "C5_result_union";
                return "C5_row_selection_or_bookkeeping";
            }
            if(has(f,".DemandStore.initials",".LoopQueryScratch.initials"))return "C2_initial_admission";
            if(has(f,".LoopObservedFacts.",".EnclosingResults."))return "observation_result_union";
            if(has(f,".LocalRelationApplication.applyRecordView",".ApOps.applyRecordLeaf"))return "reverse_saved_AP_application";
            if(has(f,".LocalRelationApplication.applyRecord"))return "direct_saved_AP_application";
            if(has(f,".PersistentRecordStore.",".Record.forEachReversedAt",".Record.reversedLeavesAt",".MethodBlockRuntime.savedRows",".MethodBlockRuntime$savedRows"))return "saved_record_enumeration";
            if(has(f,".NormalTargetStore.",".NormalTargetView."))return "normal_target_lookup";
            if(has(f,".FlowSummaryNormalizationKt.",".MethodExitMetadataKt."))return "normalization_or_metadata";
            return "observer_other";
        }
        if(domain.equals("joined_static_binding")){
            if(has(f,".LimitKt.limitFacts",".FieldLimitCut.",".ApOps.limit"))return "field_limit";
            if(has(f,".ApOps.satisfying",".SummaryKt.satisfyingPart"))return "input_matching";
            if(has(f,".ApOps.applySummary",".SummaryKt.applySummaryPart"))return "native_summary_application";
            if(has(f,".StaticWriteKeyInterner.intern",".StaticWriteKeyInterner.row"))return "raw_key_intern_or_decode";
            if(has(f,".FrozenStaticCompletion$Builder.add",".PackedGuidanceCatalog",".StaticGuidanceKt.guidancePattern"))return "guidance_publication";
            if(has(f,".CalleeSubscriptions.visitJoinedCandidates",".JoinedCallerInputs.visit",".JoinedLocalInputs.visit"))return "standing_input_selection_or_scan";
            return "binding_other";
        }
        if(domain.equals("local_publication")){
            if(has(f,".ApOps.satisfying",".SummaryKt.satisfyingPart",".LocalRelationApplication.targetArmLayer"))return "standing_input_matching";
            if(has(f,".PublicationIndex.addAll",".PublicationIndex.addTargets"))return "publication_index_admission";
            return "snapshot_scan_or_delivery_enqueue";
        }
        return domain.equals("static_prune")?"freeze":domain.equals("local_delivery")?"apply_or_queue":"other";
    }

    static final String[][] COMPONENTS={
        {"C2_initial_admission",".DemandStore.initials",".LoopQueryScratch.initials"},
        {"C5_enclosing_restriction",".DemandStore.intersect",".DemandStore.prepareLocalDataPlan",".DemandStore$prepareLocalDataPlan",".EntryRestrictionTicket.",".LoopQueryScratch.plan",".BlockBoundaryDemandView.intersect",".DemandStore.acceptsTarget",".BlockBoundaryDemandView.acceptsTarget"},
        {"normal_target_lookup",".NormalTargetStore.",".NormalTargetView."},
        {"saved_record_enumeration",".PersistentRecordStore.",".MethodBlockRuntime.savedRows",".MethodBlockRuntime$savedRows",".Record.reversedLeavesAt",".Record.forEachReversedAt"},
        {"saved_record_application",".LocalRelationApplication.applyRecord",".LocalRelationApplication.applyRecordView",".LocalRelationApplication.applyMatched",".ApOps.applyRecordLeaf"},
        {"AP_normalization_or_exit_metadata",".FlowSummaryNormalizationKt.",".MethodExitMetadataKt.",".BlockRunState.adjustObservedMethodExit",".BlockRunState.adjustMethodExitMetadata"},
        {"observation_result_union",".LoopObservedFacts.",".EnclosingResults."}
    };
    static String observerComponent(List<String> frames){
        int end=-1;for(int i=0;i<frames.size();i++)if(frames.get(i).contains(".LoopConsumerObservation")||frames.get(i).contains(".MethodBlockRuntime.observe"))end=i;
        if(end<0)return null;
        for(int i=0;i<=end;i++)for(String[] component:COMPONENTS)for(int j=1;j<component.length;j++)if(frames.get(i).contains(component[j]))return component[0];
        return "observer_control_or_other";
    }
    static final Map<String,List<String>> scopes=new LinkedHashMap<>();
    static final IdentityHashMap<RecordedStackTrace,Trace> traces=new IdentityHashMap<>();
    static final IdentityHashMap<RecordedMethod,String> methods=new IdentityHashMap<>();
    static long cacheFlushes,selectedEvents;
    static void inc(Map<String,Long> c,String k,long n){c.merge(k,n,Long::sum);}
    static String className(RecordedClass cls){String n=cls.getName();if(n.contains("+0x")){int dot=n.lastIndexOf('.');return dot>n.indexOf("+0x")?n.substring(0,dot)+"/"+n.substring(dot+1):n;}return n.replace('.','/');}
    static double seconds(Duration d){return d.getSeconds()+d.getNano()/1e9;}
    static double epoch(Instant d){return d.getEpochSecond()+d.getNano()/1e9;}
    static Trace trace(RecordedEvent e){
        RecordedStackTrace st=e.getStackTrace();
        if(st==null)return new Trace(List.of(),"other","<no bidi frame>");
        Trace old=traces.get(st);if(old!=null)return old;
        if(traces.size()>=20000){traces.clear();methods.clear();cacheFlushes++;}
        List<String> frames=new ArrayList<>();String site="<no bidi frame>";
        for(RecordedFrame f:st.getFrames()){
            RecordedMethod m=f.getMethod();
            String name=m==null?"?.?":methods.computeIfAbsent(m,x->x.getType().getName().replace('/','.')+"."+x.getName());
            frames.add(name);if(site.equals("<no bidi frame>")&&name.contains(".bidi."))site=name;
        }
        String scope="other";
        outer:for(Map.Entry<String,List<String>> row:scopes.entrySet())for(String anchor:row.getValue())for(String f:frames)
            if(f.contains(anchor)){scope=row.getKey();break outer;}
        Trace result=new Trace(frames,scope,site);traces.put(st,result);return result;
    }
    static String quote(String s){
        StringBuilder b=new StringBuilder("\"");for(int i=0;i<s.length();i++){
            char c=s.charAt(i);if(c=='"'||c=='\\')b.append('\\').append(c);else if(c=='\n')b.append("\\n");else if(c=='\r')b.append("\\r");else if(c=='\t')b.append("\\t");else if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);
        }return b.append('"').toString();
    }
    static void json(Writer w,Object o)throws IOException{
        if(o==null){w.write("null");return;}if(o instanceof String){w.write(quote((String)o));return;}
        if(o instanceof Number||o instanceof Boolean){w.write(o.toString());return;}
        if(o instanceof Map){w.write('{');boolean comma=false;for(Object item:((Map<?,?>)o).entrySet()){
            Map.Entry<?,?> e=(Map.Entry<?,?>)item;if(comma)w.write(',');comma=true;w.write(quote(e.getKey().toString()));w.write(':');json(w,e.getValue());}w.write('}');return;}
        if(o instanceof Iterable){w.write('[');boolean comma=false;for(Object x:(Iterable<?>)o){if(comma)w.write(',');comma=true;json(w,x);}w.write(']');return;}
        throw new IllegalArgumentException("unsupportedJSON "+o.getClass());
    }
    public static void main(String[] args)throws Exception{
        List<Window> windows=new ArrayList<>();for(String line:Files.readAllLines(Path.of(args[1]))){String[] p=line.split("\\t");windows.add(new Window(p[0],Double.parseDouble(p[1]),Double.parseDouble(p[2])));}
        for(String line:Files.readAllLines(Path.of(args[2]))){String[] p=line.split("\\t");scopes.put(p[0],Arrays.asList(p).subList(1,p.length));}
        Counts total=new Counts();double first=Double.POSITIVE_INFINITY,last=Double.NEGATIVE_INFINITY,totalPause=0;long pauses=0;
        try(RecordingFile file=new RecordingFile(Path.of(args[0]))){while(file.hasMoreEvents()){
            RecordedEvent e=file.readEvent();String kind=e.getEventType().getName();
            if(!kind.equals("jdk.ExecutionSample")&&!kind.equals("jdk.ObjectAllocationSample")&&!kind.equals("jdk.GarbageCollection")&&!kind.equals("jdk.GCPhasePause"))continue;
            selectedEvents++;double stamp=epoch(e.getStartTime());first=Math.min(first,stamp);last=Math.max(last,stamp);
            Trace t=(kind.equals("jdk.ExecutionSample")||kind.equals("jdk.ObjectAllocationSample"))?trace(e):null;
            total.add(kind,e,t);
            if(kind.equals("jdk.GCPhasePause")){double duration=seconds(e.getDuration());totalPause+=duration;pauses++;
                for(Window w:windows){double amount=Math.max(0,Math.min(stamp+duration,w.end)-Math.max(stamp,w.begin));if(amount>0){w.pauseSeconds+=amount;w.pauseEvents++;}}}
            for(Window w:windows)if(w.begin<=stamp&&stamp<w.end)w.counts.add(kind,e,t);
        }}
        Map<String,Object> out=new LinkedHashMap<>();out.put("firstSelectedEventEpoch",Double.isFinite(first)?first:null);out.put("lastSelectedEventEpoch",Double.isFinite(last)?last:null);out.put("selectedEvents",selectedEvents);out.put("traceCacheFlushes",cacheFlushes);out.put("continuous",total.output());out.put("topLevelPauseSeconds",totalPause);out.put("topLevelPauseEvents",pauses);
        Map<String,Object> grouped=new LinkedHashMap<>();for(Window w:windows){Map<String,Object> c=w.counts.output();c.put("pauseSeconds",w.pauseSeconds);c.put("pauseEvents",w.pauseEvents);grouped.put(w.name,c);}out.put("windows",grouped);
        try(BufferedWriter writer=Files.newBufferedWriter(Path.of(args[3]))){json(writer,out);writer.write('\n');}
    }
}
